348	/* Returns the value stored under key, or NULL if absent. Tree retains ownership. */
349	void *rb_find(const rbtree_t *t, const char *key) {
350	    if (t == NULL || key == NULL) {
351	        return NULL;
352	    }
353	    const rb_node_t *x = t->root;
354	    /* invariant: key, if present, lies in the subtree rooted at x */
355	    while (x != t->nil) {
356	        int c = strcmp(key, x->key);
357	        if (c == 0) {
358	            return x->value;
359	        }
360	        x = (c < 0) ? x->left : x->right;
361	    }
362	    return NULL;
363	}
