483	/* Removes key; frees the key copy and (if owned) the value. Returns 0, or -1
484	 * if key is absent (tree unchanged). */
485	int rb_delete(rbtree_t *t, const char *key) {
486	    if (t == NULL || key == NULL) {
487	        return -1;
488	    }
489	
490	    /* phase 1: BST search for z, mirroring rb_find's descent.
491	     * invariant: key, if present, lies in the subtree rooted at z */
492	    rb_node_t *z = t->root;
493	    while (z != t->nil) {
494	        int c = strcmp(key, z->key);
495	        if (c == 0) {
496	            break;
497	        }
498	        z = (c < 0) ? z->left : z->right;
499	    }
500	    if (z == t->nil) {
501	        return -1; /* absent: tree, size, and validity all unchanged */
502	    }
503	
504	    /* phase 2: CLRS splice. y is the node actually removed from its spot
505	     * (equal to z unless z has two children); x is the node that lands in
506	     * y's old position, possibly t->nil. */
507	    rb_node_t *y = z;
508	    rb_color_t y_original_color = y->color;
509	    rb_node_t *x;
510	
511	    if (z->left == t->nil) {
512	        x = z->right;
513	        rb_transplant(t, z, z->right);
514	    } else if (z->right == t->nil) {
515	        x = z->left;
516	        rb_transplant(t, z, z->left);
517	    } else {
518	        y = rb_minimum(t, z->right);
519	        y_original_color = y->color;
520	        x = y->right;
521	        if (y->parent == z) {
522	            x->parent = y; /* needed even if x == t->nil */
523	        } else {
524	            rb_transplant(t, y, y->right);
525	            y->right = z->right;
526	            y->right->parent = y;
527	        }
528	        rb_transplant(t, z, y);
529	        y->left = z->left;
530	        y->left->parent = y;
531	        y->color = z->color;
532	    }
533	
534	    /* phase 3: release z's payload. Nothing in the tree references z anymore
535	     * -- everything that pointed at z now points at y or at whatever
536	     * replaced it. The value != NULL guard mirrors rb_insert's overwrite
537	     * path: avoid handing a NULL to a possibly non-NULL-safe value_free. */
538	    free(z->key);
539	    if (t->value_free != NULL && z->value != NULL) {
540	        t->value_free(z->value);
541	    }
542	    free(z);
543	    t->size--;
544	
545	    /* phase 4: restore invariants only if a black node was physically
546	     * removed -- splicing out a red node changes no black-height and cannot
547	     * create a red-red violation. */
548	    if (y_original_color == BLACK) {
549	        rb_delete_fixup(t, x);
550	    }
551	
552	    /* phase 5: sentinel hygiene. Unlike CLRS's implicit T.nil, this tree's
553	     * nil is one object shared for the tree's whole lifetime, so restore its
554	     * self-referential shape (rb_create's invariant) rather than leaving a
555	     * stale parent pointer from this call. */
556	    t->nil->parent = t->nil;
557	
558	    return 0;
559	}

