            shadow_count++;
            if (!cc.visited[k]) {
                cc.ok = 0;
            }
        }
    }

    if (!cc.ok || cc.count != rb_size(t) || cc.count != shadow_count) {
        fprintf(stderr,
            "fuzz: cross-check failed at iteration %ld: visited=%zu rb_size=%zu "
            "shadow_count=%zu bad_key=%s expected=%p actual=%p\n",
